#include <cuda_runtime.h>
#include <vector>
#include <algorithm>
#define main legacy_main
#include "../attentionMergeState-cuda/main.cu"
#undef main
#define CK(x) do{auto e=(x);if(e!=cudaSuccess){fprintf(stderr,"%s\n",cudaGetErrorString(e));exit(1);}}while(0)
struct Metrics{double t;float ma,mr;bool ok;std::vector<float>output;};
template<class T>Metrics run(int repeat){int tokens=128,heads=8,size=64,n=tokens*heads*size,ln=tokens*heads;std::vector<T>p(n),s(n),out(n),ro(n);std::vector<float>pl(ln),sl(ln),rl(ln),l(ln);for(int i=0;i<n;i++){from_float32(p[i],float((13*i+7)%129-64)/128.f);from_float32(s[i],float((37*i+11)%129-64)/128.f);}for(int i=0;i<ln;i++){pl[i]=float((13*i+7)%129-64)/16.f;sl[i]=float((37*i+11)%129-64)/16.f;}for(int i=0;i<32;i++){pl[i]=i%2==0?INFINITY:-INFINITY;sl[32+i]=i%2==0?INFINITY:-INFINITY;}reference<T>(ro.data(),p.data(),s.data(),rl.data(),pl.data(),sl.data(),tokens,heads,size);static T *dp,*ds,*dout;static float *dpl,*dsl,*dl;static bool initialized=false;if(!initialized){CK(cudaMalloc(&dp,n*sizeof(T)));CK(cudaMalloc(&ds,n*sizeof(T)));CK(cudaMalloc(&dout,n*sizeof(T)));CK(cudaMalloc(&dpl,ln*4));CK(cudaMalloc(&dsl,ln*4));CK(cudaMalloc(&dl,ln*4));CK(cudaMemcpy(dp,p.data(),n*sizeof(T),cudaMemcpyHostToDevice));CK(cudaMemcpy(ds,s.data(),n*sizeof(T),cudaMemcpyHostToDevice));CK(cudaMemcpy(dpl,pl.data(),ln*4,cudaMemcpyHostToDevice));CK(cudaMemcpy(dsl,sl.data(),ln*4,cudaMemcpyHostToDevice));}auto launch=[&](){int pack=16/sizeof(T),threads=tokens*heads*(size/pack);merge_attn_states_kernel<T,256><<<(threads+255)/256,256>>>(dout,dp,ds,dl,dpl,dsl,tokens,heads,size);};if(!initialized){launch();CK(cudaDeviceSynchronize());initialized=true;}CK(cudaMemset(dout,0,n*sizeof(T)));CK(cudaMemset(dl,255,ln*4));CK(cudaDeviceSynchronize());auto t0=std::chrono::steady_clock::now();for(int k=0;k<repeat;k++)launch();CK(cudaDeviceSynchronize());Metrics m;m.t=std::chrono::duration<double>(std::chrono::steady_clock::now()-t0).count()/repeat;m.ma=0;m.mr=0;m.ok=true;CK(cudaMemcpy(out.data(),dout,n*sizeof(T),cudaMemcpyDeviceToHost));CK(cudaMemcpy(l.data(),dl,ln*4,cudaMemcpyDeviceToHost));for(int i=0;i<n+ln;i++){float g=i<n?to_float32(out[i]):l[i-n],ref=i<n?to_float32(ro[i]):rl[i-n],e=fabsf(g-ref);m.ma=fmaxf(m.ma,e);m.mr=fmaxf(m.mr,e/fmaxf(fabsf(ref),1.1920929e-7f));m.ok&=std::isfinite(g)&&e<=1e-3f;m.output.push_back(g);}return m;}
int main(int argc,char**argv){int repeat=argc>1?atoi(argv[1]):100;bool all=true;for(int trial=1;trial<=5;trial++){auto a=run<float>(repeat),b=run<half>(repeat),c=run<__nv_bfloat16>(repeat);std::vector<float>output=a.output;output.insert(output.end(),b.output.begin(),b.output.end());output.insert(output.end(),c.output.begin(),c.output.end());bool ok=a.ok&&b.ok&&c.ok;all&=ok;char file[100];sprintf(file,"attention_trial%d.bin",trial);FILE*f=fopen(file,"wb");fwrite(output.data(),4,output.size(),f);fclose(f);printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%d,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"sum_real_FP32_FP16_BF16_attention_merge_regions_per_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"dtype_times_seconds\":[%.12g,%.12g,%.12g],\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%d,\"byte_order\":\"little\"}}\n",trial,a.t+b.t+c.t,ok?"true":"false",int(output.size()),fmaxf(a.ma,fmaxf(b.ma,c.ma)),fmaxf(a.mr,fmaxf(b.mr,c.mr)),repeat,a.t,b.t,c.t,file,int(output.size()));}puts(all?"PASS":"FAIL");return all?0:1;}
